@props(['label','value','unit'=>'','icon'=>'chart','note'=>'','href'=>null,'tone'=>'blue'])<div {{ $attributes->merge(['class'=>'kpi kpi-'.$tone.($href?' kpi-clickable':'')]) }}><div class="kpi-top"><span>{{ $label }}</span><span class="kpi-icon"><x-icon :name="$icon"/></span></div><div class="kpi-value"><span data-count-value="{{ $value }}" data-count-decimals="{{ floor((float)$value)==(float)$value?0:1 }}" aria-hidden="true">{{ number_format($value,floor((float)$value)==(float)$value?0:1,',','.') }}</span><span class="visually-hidden">{{ number_format($value,1,',','.') }}</span> <small>{{ $unit }}</small></div><div class="kpi-foot">{{ $note }}</div>@if($href)<a href="{{ $href }}" class="stretched-link" aria-label="Lihat {{ $label }}"><x-icon name="arrow" class="kpi-link-icon"/></a>@endif</div>